}
.wine-card-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--atlas-text);
  margin-bottom: 6px;
}
.wine-card-rating {
  font-size: 0.9rem;
  color: var(--atlas-tint);
  margin-bottom: 6px;
  letter-spacing: 1px;
}
.wine-card-notes {
  font-size: 0.82rem;
  color: var(--atlas-text-secondary);
  margin-bottom: 10px;
  line-height: 1.5;
}
.wine-card-taste { margin-top: 8px; }
.wine-card-taste-label {
