}

/* Atlas info panel — fade in on content change */
@keyframes atlas-panel-enter {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.atlas-panel-fade {
  animation: atlas-panel-enter 0.25s ease-out;
}

/* Atlas layout — stacked on mobile, side panel on desktop */
.atlas-layout {
  display: flex;
  flex-direction: column;
}

.atlas-main {
  flex: 1;
  min-width: 0;
}

.atlas-sidebar {
  margin-top: 0;
}

@media (min-width: 1024px) {
  .atlas-layout {
    flex-direction: row;
    gap: 20px;
    align-items: flex-start;
  }

  .atlas-sidebar {
    width: 340px;
    flex-shrink: 0;
    position: sticky;
    top: 20px;
    align-self: flex-start;
    z-index: 1;
  }
}

/* Silly Jam maker's-mark colophon — a quiet publisher's seal at the foot of the page */
.sj-mark-wrap {
  margin-top: 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.65rem;
}

.sj-colophon {
  display: inline-flex;
  align-items: center;
  gap: 0.45em;
  color: var(--atlas-text-placeholder);
  font-size: 0.72rem;
  letter-spacing: 0.05em;
  transition: color 0.2s ease;
}

/* The jar sits a touch dimmer than the caption, then both warm on hover
   and the jar "presses in" 1px like a stamp. */
.sj-jar {
  opacity: 0.55;
  transition: opacity 0.2s ease, transform 0.15s ease;
}

.sj-colophon:hover {
  color: var(--atlas-text);
}

.sj-colophon:hover .sj-jar {
  opacity: 1;
  transform: translateY(1px);
}

@media (prefers-reduced-motion: reduce) {
  .sj-jar {
    transition: opacity 0.2s ease;
  }
  .sj-colophon:hover .sj-jar {
    transform: none;
  }
}

/* Antique Mappe-Monde wash behind the hero wine glass — printed into the
   cream paper via multiply, cropped to a soft circle over one hemisphere.
   Tuning knobs: --hero-map-opacity, background-position (which hemisphere),
   background-size (zoom). */
.hero-map {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image: url("/vynr-world-map.jpg?v=7");
  background-repeat: no-repeat;
  background-size: cover;
  background-position: 26% center;
  opacity: 0.14;
  mix-blend-mode: multiply;
  /* Fill the whole canvas edge-to-edge; fade ONLY into the header/footer
     separator lines so there is no mid-canvas boundary. Paper is pre-baked to
     white, so multiply renders it as the exact page cream (no tonal seam). */
  -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0) 0%, #000 6%, #000 94%, rgba(0, 0, 0, 0) 100%);
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0) 0%, #000 6%, #000 94%, rgba(0, 0, 0, 0) 100%);
  animation: heroMapFade 700ms ease-out both;
}

@keyframes heroMapFade {
  from {
    opacity: 0;
  }
  to {
    opacity: 0.14;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-map {
    animation: none;
  }
}

/* Desktop: fill the full viewport width, bounded to the hero height. Cover
   crops out the ornate top/bottom cartouches, leaving clean hemispheres
   spanning edge to edge; only the top/bottom fade into the cream so it
   doesn't hard-cut at the header/footer borders. */
@media (min-width: 680px) {
  .hero-map {
    left: 50%;
    right: auto;
    top: 0;
    bottom: 0;
    width: 100vw;
    height: auto;
    transform: translateX(-50%);
    background-size: cover;
    background-position: center;
    -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0) 0%, #000 14%, #000 86%, rgba(0, 0, 0, 0) 100%);
    mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0) 0%, #000 14%, #000 86%, rgba(0, 0, 0, 0) 100%);
  }
}

/* 44px minimum tap target for chrome links without changing visual size */
.tap-target {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  min-width: 44px;
  padding: 0 0.5rem;
  box-sizing: border-box;
}

/* Site chrome — header with the site menu, and the one-line footer.
   Every link carries .tap-target (44px). */
.site-nav {
  max-width: 720px;
  margin: 0 auto;
  padding: 4px 24px;
  box-sizing: border-box;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
}

.site-wordmark {
  margin-left: -0.5rem; /* the tap-target padding, so the wordmark still aligns with the content edge */
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--atlas-text);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.site-nav-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  align-items: center;
  margin-right: -0.5rem;
}

.nav-link {
  gap: 0.4em;
  font-size: 0.875rem;
  color: var(--atlas-text-secondary);
  text-decoration: none;
  transition: color 0.15s ease;
}

.nav-link:hover {
  color: var(--atlas-text);
}

.site-footer {
  border-top: 1px solid var(--atlas-separator);
  padding: 0.75rem 1.5rem 1rem;
  text-align: center;
  color: var(--atlas-text-secondary);
  font-size: 0.8rem;
  letter-spacing: 0.02em;
}

.site-footer .nav-link {
  font-size: inherit;
  vertical-align: middle;
}

.footer-dot {
  margin: 0 0.25rem;
  opacity: 0.4;
}

.site-nav-start {
  display: flex;
  align-items: center;
  margin-left: -0.75rem; /* the menu button's tap-target padding: its icon aligns with the content edge */
}

.site-nav-start .site-wordmark {
  margin-left: 0;
}

.site-nav {
  position: relative;
}

.site-menu-button {
  padding: 0 0.75rem;
  background: none;
  border: 0;
  color: var(--atlas-text-secondary);
  cursor: pointer;
}

.site-menu-button:hover,
.site-menu-button[aria-expanded="true"] {
  color: var(--atlas-text);
}

/* A quiet sheet under the header: full width on phones, a small panel on wider screens.
   It hangs from the nav's real bottom edge (plus the header's 1px rule), so a header that
   wraps under large text never hides it, and it scrolls within itself on short screens. */
.site-menu-panel {
  position: absolute;
  top: calc(100% + 1px);
  left: 0;
  right: 0;
  z-index: 60;
  max-height: calc(100dvh - 100%);
  overflow-y: auto;
  padding: 0.5rem 24px 1rem;
  background: var(--chrome-bg);
  border-bottom: 1px solid var(--atlas-separator);
  box-shadow: 0 8px 16px -12px rgba(61, 53, 40, 0.35);
}

.site-menu-panel[hidden] {
  display: none;
}

.site-menu-group + .site-menu-group {
  border-top: 1px solid var(--atlas-separator);
  margin-top: 0.25rem;
  padding-top: 0.25rem;
}

.site-menu-label {
  margin: 0.5rem 0 0;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--atlas-text-secondary);
}

.site-menu-group ul {
  list-style: none;
  margin: 0 0 0 -0.5rem;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
}

.site-menu-group .nav-link[aria-current="page"] {
  color: var(--atlas-text);
  font-weight: 600;
}

@media (min-width: 640px) {
  .site-menu {
    position: relative;
  }

  .site-menu-panel {
    top: calc(100% + 5px);
    right: auto;
    min-width: 240px;
    border: 1px solid var(--atlas-separator);
    border-radius: 6px;
    padding: 0.25rem 1rem 0.75rem;
  }

  .site-menu-group ul {
    flex-direction: column;
    align-items: flex-start;
  }
}

.sj-colophon {
  min-height: 44px;
}

/* Roadmap — rendered from ROADMAP.md. A quiet reading column with scan structure:
   a jump index, release bands edged by commitment level, and bordered feedback callouts. */
.roadmap [id],
.plans [id] {
  scroll-margin-top: 64px; /* clear the sticky header when jumping to a section */
}

.roadmap blockquote,
.plans blockquote {
  margin: 1.5rem 0;
  padding: 0.85rem 1.1rem;
  border: 1px solid var(--atlas-separator);
  border-left: 3px solid var(--atlas-link);
  border-radius: 4px;
  font-style: normal; /* no fill: links keep AA contrast on the page background */
  color: var(--atlas-text);
}

.roadmap blockquote p,
.plans blockquote p {
  margin: 0;
}

.roadmap-index {
  display: flex;
  flex-wrap: wrap;
  gap: 0 0.25rem;
  margin: 1.5rem 0 0;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--atlas-separator);
}

.roadmap-index .nav-link:first-child {
  padding-left: 0; /* text, not tap padding, aligns with the column; the rule stays inside it */
  justify-content: flex-start;
}

/* Scannable lists: quiet disc markers (the site's base styles strip them). */
.roadmap ul,
.plans ul {
  list-style: disc;
  padding-left: 1.25rem;
}

.roadmap li,
.plans li {
  margin-bottom: 0.35rem;
}

.roadmap li::marker,
.plans li::marker {
  color: var(--atlas-tint);
}

.roadmap-index .nav-link {
  color: var(--atlas-link);
  text-decoration: none;
}

.roadmap-section > h2 {
  margin-top: 3rem;
}

.release-band {
  margin: 1.75rem 0 0;
  padding: 0.25rem 0 0.25rem 1.1rem;
  border-left: 2px solid var(--atlas-separator);
}

.release-band[data-commitment="launch"] {
  border-left-color: var(--atlas-text-secondary);
}

.release-band[data-commitment="planned-next"] {
  border-left-color: var(--atlas-link);
}

.release-band[data-commitment="directional-later"] {
  border-left-style: dashed;
}

.release-band h3 {
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 0.6rem;
}

.release-version {
  font-variant-numeric: tabular-nums;
  color: var(--atlas-link);
}

.release-meta {
  margin: 0.2rem 0 0.75rem;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.15rem 0.75rem;
}

.release-commitment {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--atlas-text-secondary);
}

.release-promise {
  font-style: italic;
  color: var(--atlas-text);
}

.release-band h4 {
  margin: 1.25rem 0 0.25rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--atlas-text);
}

/* vynr and vynr+ — rendered from VYNR-PLUS.md. The comparison is a real table:
   three columns on wide screens, one small stacked block per row on phones. */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.plans-table {
  width: 100%;
  margin: 1rem 0 0;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.plans-table th,
.plans-table td {
  padding: 0.7rem 0.75rem 0.7rem 0;
  text-align: left;
  vertical-align: top;
  border-top: 1px solid var(--atlas-separator);
}

.plans-table thead th {
  border-top: 0;
  padding-bottom: 0.4rem;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  /* Small caps rather than an uppercase transform, so the accessible name stays "vynr". */
  font-variant-caps: all-small-caps;
  color: var(--atlas-text-secondary);
}

.plans-table tbody th {
  width: 22%;
  font-weight: 600;
  color: var(--atlas-text);
}

.plans-table td p {
  margin: 0;
}

.plans-table td[data-plan="vynr+"] {
  color: var(--atlas-text);
}

@media (max-width: 639px) {
  /* Visually hidden, never display:none: the headers stay in the accessibility tree. */
  .plans-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
  }

  .plans-table,
  .plans-table tbody,
  .plans-table tbody tr,
  .plans-table th,
  .plans-table td {
    display: block;
    width: auto;
  }

  .plans-table tr {
    padding: 0.75rem 0;
    border-top: 1px solid var(--atlas-separator);
  }

  .plans-table th,
  .plans-table td,
  .plans-table tbody th {
    width: auto;
    border-top: 0;
    padding: 0.15rem 0;
  }

  /* Label and text side by side, so wrapped text hangs beside its plan name. */
  .plans-table td {
    display: grid;
    grid-template-columns: 3.5rem 1fr;
    align-items: baseline;
  }

  /* The column header is hidden on phones, so each cell names its plan visually. The
     alt text "" keeps this label out of the accessibility tree: the header already names it. */
  .plans-table td::before {
    content: attr(data-plan) / "";
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    color: var(--atlas-text-secondary);
  }

}

/* Guide to vynr (SJAM-1041, spec §6: the scrolling story). The shot overlay keeps the app's
   own colours inside its SVG; everything around it uses the site tokens. The base rules are the
   complete linear page; `.is-enhanced` (set by GuideStoryEnhancer on wide screens) pins the
   phone beside the steps. Reduce Motion keeps the highlighting and drops every animation. */
.guide { max-width: 1040px; margin: 0 auto; padding: 56px 24px 96px; }
.guide a { color: var(--atlas-link); }
.guide-header { margin-bottom: 3rem; }
.guide-header h1 {
  font-size: 2.5rem; font-weight: 600; letter-spacing: -0.02em; line-height: 1.15;
  color: var(--atlas-text); margin: 0 0 0.875rem;
}
.guide-header p { color: var(--atlas-text-secondary); max-width: 640px; font-size: 1.125rem; line-height: 1.55; }
.guide-rule { width: 40px; height: 2px; background: var(--atlas-tint); margin-top: 1.5rem; border-radius: 1px; }
.guide-kicker {
  font-size: 0.8125rem; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--atlas-text-placeholder); font-weight: 600; margin: 0 0 0.5rem;
}
.guide-back { font-size: 0.875rem; margin-bottom: 1.5rem; }

.guide-map {
  border: 1px solid var(--atlas-card-stroke); border-radius: 18px; padding: 28px;
  margin-bottom: 4.5rem; background: color-mix(in srgb, var(--atlas-card) 35%, var(--atlas-bg));
}
.guide-map-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; margin-top: 1.25rem; }
.guide .guide-map-node { display: flex; flex-direction: column; gap: 12px; text-decoration: none; color: var(--atlas-text); }
.guide-map-caption { font-weight: 600; font-size: 1.0625rem; text-decoration: underline; text-decoration-color: var(--atlas-separator); text-underline-offset: 3px; }
.guide-map-node:hover .guide-map-caption { text-decoration-color: var(--atlas-tint); }
.guide-map-stack { display: flex; flex-direction: column; gap: 4px; max-width: 180px; }
.guide-map-stack-item { display: flex; flex-direction: column; gap: 4px; }
.guide-map-flick { text-align: center; color: #8C7360; font-size: 0.8125rem; }
.guide-map-tile {
  border: 1px solid var(--atlas-card-stroke); border-radius: 10px; background: var(--atlas-card);
  padding: 6px 12px; font-size: 0.875rem; font-weight: 600; text-align: center;
}
.guide-map-tile.is-held { border-color: #8C7360; box-shadow: 0 0 0 2px color-mix(in srgb, #8C7360 25%, transparent); }
.guide-map-switcher {
  display: flex; flex-direction: column; max-width: 210px; border-radius: 12px; background: #262420;
  color: var(--atlas-bg); padding: 12px 14px; font-size: 0.8125rem; line-height: 1.9;
}
.guide-map-place { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; max-width: 240px; }
.guide-map-place-item { display: inline-flex; align-items: center; gap: 6px; }
.guide-map-place .guide-map-tile { font-weight: 500; }
.guide-map-sep { color: #8C7360; }

.guide-group-heading {
  font-size: 0.8125rem; letter-spacing: 0.12em; text-transform: uppercase; font-weight: 600;
  color: var(--atlas-text-placeholder); border-top: 1px solid var(--atlas-separator);
  padding-top: 1rem; margin: 0 0 2.5rem;
}
.guide-chapter { margin-bottom: 5.5rem; scroll-margin-top: 64px; } /* clear the sticky site header, as elsewhere */
.guide-chapter-title {
  font-size: 1.875rem; font-weight: 600; letter-spacing: -0.015em; color: var(--atlas-text); margin: 0 0 0.625rem;
}
.guide-lede { font-size: 1.0625rem; line-height: 1.55; color: var(--atlas-text-secondary); max-width: 620px; margin-bottom: 1.75rem; }

.guide-shot { position: relative; max-width: 100%; border-radius: 18px; overflow: hidden; }
.guide-shot img { display: block; width: 100%; height: 100%; }
.guide-shot svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.guide-inline-shot { margin: 0.5rem 0 1.25rem; }
.guide-step-list { list-style: none; padding: 0; margin: 0 0 1.5rem; }
.guide-step { display: flex; gap: 12px; align-items: baseline; font-size: 1.0625rem; line-height: 1.55; color: var(--atlas-text); margin-bottom: 1.25rem; }
.guide-badge {
  flex: none; width: 24px; height: 24px; border-radius: 50%; background: #262420; color: #fff;
  font-size: 0.8125rem; font-weight: 700; font-variant-numeric: tabular-nums;
  display: inline-flex; align-items: center; justify-content: center;
}
.guide-phone-col { display: none; }
.guide-body { margin-top: 1rem; }

/* Wide screens with JavaScript: the pinned phone follows the step being read. */
.guide-chapter.is-enhanced .guide-story {
  display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: 64px; align-items: start;
}
/* Visually hidden, not removed: the inline shot keeps its alt text for assistive technology,
   since the pinned-phone copy beside it is aria-hidden. */
.guide-chapter.is-enhanced .guide-inline-shot {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;
}
.guide-chapter.is-enhanced .guide-step {
  min-height: 55vh; align-items: center; margin: 0; opacity: 0.4; transition: opacity 0.3s;
}
.guide-chapter.is-enhanced .guide-step.is-on { opacity: 1; }
.guide-chapter.is-enhanced .guide-phone-col { display: block; position: sticky; top: 80px; } /* below the sticky site header */
.guide-phone {
  position: relative; width: 300px; height: 540px; border-radius: 46px; background: #262420;
  padding: 20px 10px; box-sizing: border-box;
}
.guide-screen { position: relative; width: 280px; height: 500px; }
.guide-phone-shot {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  opacity: 0; transition: opacity 0.35s;
}
.guide-phone-shot.is-shown { opacity: 1; }
/* Fit each shot inside the 280 × 500 screen at its own aspect ratio, tall or wide. */
.guide-phone-shot .guide-shot { width: min(280px, calc(500px * var(--guide-aspect))) !important; }
.guide-c { transition: opacity 0.3s; }
.guide-phone.has-active .guide-c:not(.is-on) { opacity: 0.14; }
.guide-phone .guide-c.is-on .guide-mv { stroke-dasharray: 1; animation: guide-draw 0.9s ease-out 0.2s both; }
.guide-phone .guide-c.is-on .guide-hr {
  transform-box: fill-box; transform-origin: center; animation: guide-ring 1.1s ease-out 0.3s both;
}
.guide-phone .guide-c.is-on .guide-hr-outer { animation-delay: 0.55s; }
@keyframes guide-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes guide-ring { 0% { opacity: 0; transform: scale(0.55); } 70% { opacity: 1; } 100% { opacity: 1; transform: scale(1); } }

.guide-nav {
  display: flex; justify-content: space-between; gap: 16px;
  border-top: 1px solid var(--atlas-separator); padding-top: 1rem; margin-top: 1rem;
}
.guide-stamp { margin-top: 2rem; font-size: 0.8125rem; color: var(--atlas-text-placeholder); }

@media (prefers-reduced-motion: reduce) {
  .guide-phone-shot, .guide-c, .guide-chapter.is-enhanced .guide-step { transition: none; }
  .guide-phone .guide-c.is-on .guide-mv, .guide-phone .guide-c.is-on .guide-hr { animation: none; }
}
/* Print is the linear page, whatever the screen width enhancement did. */
@media print {
  .guide-chapter.is-enhanced .guide-story { display: block; }
  .guide-chapter.is-enhanced .guide-inline-shot {
    position: static; width: auto; height: auto; margin: 0.5rem 0 1.25rem; clip-path: none; overflow: visible; white-space: normal;
  }
  .guide-chapter.is-enhanced .guide-phone-col { display: none; }
  .guide-chapter.is-enhanced .guide-step { min-height: 0; opacity: 1; }
}
@media (max-width: 759px) {
  .guide-map-grid { grid-template-columns: minmax(0, 1fr); }
}
